import {chromium} from 'playwright';
import assert from 'node:assert/strict';
import {writeFile} from 'node:fs/promises';
import {openCalculatorDisclosure} from './calculator-ui-test-helpers.mjs';
const base=process.env.LABNEST_E2E_BASE_URL||'http://localhost:3251';
const browser=await chromium.launch(),context=await browser.newContext(),p=await context.newPage();const checks=[];
try{
 await p.goto(base+'/tools/calculator/dilution',{waitUntil:'networkidle'});await p.getByRole('button',{name:'Load example',exact:true}).click();
 await openCalculatorDisclosure(p,'Offline use');
 await context.route('**/icons/lab-soft-v1/resources.json',route=>route.fulfill({status:503,body:'synthetic failure'}));
 await p.getByRole('button',{name:'Prepare offline',exact:true}).click();await p.getByText(/A required page or resource failed/).waitFor();assert(await p.getByRole('button',{name:'Retry',exact:true}).isVisible());assert.equal(await p.getByText(/^Available offline:/).count(),0);checks.push('Preparation failure does not claim offline availability and offers Retry');
 await context.unroute('**/icons/lab-soft-v1/resources.json');await p.getByRole('button',{name:'Retry',exact:true}).click();await p.getByText(/^Available offline:/).waitFor({timeout:60000});assert(await p.getByRole('button',{name:'Update offline content',exact:true}).isVisible());const status=await p.getByText(/^Available offline:/).innerText();assert(status.includes('/tools/calculator/dilution'));assert(!status.includes('/tools/calculator/tm'));
 await p.getByRole('button',{name:'Update offline content',exact:true}).click();await p.getByText(/^Available offline:/).waitFor({timeout:60000});await p.getByRole('button',{name:'Close',exact:true}).click();
 await context.setOffline(true);await p.reload({waitUntil:'domcontentloaded'});await p.getByRole('heading',{name:'Dilution & dosing',exact:true}).waitFor();await p.getByRole('button',{name:'Restore draft',exact:true}).click();await p.getByRole('button',{name:'Calculate',exact:true}).click();assert(await p.locator('[data-calculator-result]').count());checks.push('Successful preparation and update cache home/current; actual disconnected reload restores draft and calculates');await context.setOffline(false);
 // Seed an explicitly blocked synthetic queue item, which the synchronizer must not submit.
 await p.evaluate(async()=>{const req=indexedDB.open('labnest-mobile-mutations',1);const db=await new Promise((resolve,reject)=>{req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('mutations'))req.result.createObjectStore('mutations',{keyPath:'clientMutationId'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});await new Promise((resolve,reject)=>{const tx=db.transaction('mutations','readwrite');tx.objectStore('mutations').put({clientMutationId:'synthetic-cache-preservation',state:'blocked',actionType:'calculation.create',payload:{synthetic:true}});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();});
 const readQueue=()=>p.evaluate(async()=>{const req=indexedDB.open('labnest-mobile-mutations',1);const db=await new Promise(resolve=>req.onsuccess=()=>resolve(req.result));const r=db.transaction('mutations').objectStore('mutations').getAll();const data=await new Promise(resolve=>r.onsuccess=()=>resolve(r.result));db.close();return JSON.stringify(data);});
 await openCalculatorDisclosure(p,'Offline use');await p.evaluate(()=>{const k='labnest.calculators.v1',s=JSON.parse(localStorage.getItem(k));s.presets=[{id:'cache-preset',calculatorId:'dilution',name:'Synthetic retained preset',createdAt:'2026-09-15',methodVersion:'dilution-v3',inputs:{mode:'final',finalVolumeUnit:'µL'}}];s.history=[{id:'cache-history',calculatorId:'dilution',createdAt:'2026-09-15',inputs:{mode:'final'},outputs:[{key:'volume',value:10,unit:'µL'}],warnings:[]}];localStorage.setItem(k,JSON.stringify(s));});const before=await p.evaluate(()=>localStorage.getItem('labnest.calculators.v1')),queue=await readQueue();await p.getByRole('button',{name:'Clear offline caches',exact:true}).click();await p.getByText('Offline caches cleared; drafts, presets, history and sync queue retained.',{exact:true}).waitFor();assert.equal(await p.evaluate(()=>localStorage.getItem('labnest.calculators.v1')),before);assert.equal(await readQueue(),queue);assert(await p.getByRole('button',{name:'Prepare offline',exact:true}).isVisible());checks.push('Clear preserves exact calculator storage and blocked IndexedDB queue; action returns to Prepare');
}catch(e){checks.push({failure:String(e)});throw e;}finally{await writeFile('docs/calculator/presets-20260915/evidence/offline.json',JSON.stringify({base,checks},null,2));await browser.close();}
